# ButtonGroup ButtonGroup ## Использование Использование Компонент  `ButtonGroup`  - это обертка для Button. Принимает в себя группу кнопок. ```tsx
import React from 'react';
import { ButtonGroup, Button } from '@salutejs/sdds-finai';

export function App() {
    return (
        <ButtonGroup>
            {Array(5)
                .fill(true)
                .map((_, i) => (
                    <Button text={`Button ${i}`} />
                ))}
        </ButtonGroup>
    );
}
```

## Примеры Примеры ### Размер и вид группы кнопок Размер и вид группы кнопок Размер и вид группы кнопок задается с помощью свойств  `size`  и  `view`  соответственно.
Значение  `view="gradient"`  задаёт кнопкам группы градиентный фон.
С помощью свойства  `isCommonButtonStyles`  можно отключить переопределение стилей для всех кнопок внутри группы.
Тогда каждая кнопка будет иметь настраиваемый размер и вид. ```tsx
import React from 'react';
import { ButtonGroup, Button } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div>
            <ButtonGroup size="s" view="secondary">
                {Array(5)
                    .fill(true)
                    .map((_, i) => (
                        <Button text={`Button ${i}`} />
                    ))}
            </ButtonGroup>

            <ButtonGroup size="s" view="gradient">
                {Array(5)
                    .fill(true)
                    .map((_, i) => (
                        <Button text={`Button ${i}`} />
                    ))}
            </ButtonGroup>

            <ButtonGroup isCommonButtonStyles={false}>
                <Button size="s" text="Primary" view="primary" />
                <Button size="xs" text="Positive" view="positive" />
            </ButtonGroup>
        </div>
    );
}
```

### Ориентация группы кнопок и отступы между кнопками Ориентация группы кнопок и отступы между кнопками Группа кнопок может располагаться вертикально или горизонтально и иметь три вида отступов: ```tsx
import React from 'react';
import { ButtonGroup, Button } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div>
            <ButtonGroup size="xs" orientation="vertical" gap="none">
                {Array(5)
                    .fill(true)
                    .map((_, i) => (
                        <Button text={`Button ${i}`} />
                    ))}
            </ButtonGroup>

            <ButtonGroup size="xs" orientation="horizontal" gap="wide">
                {Array(4)
                    .fill(true)
                    .map((_, i) => (
                        <Button text={`Button ${i}`} />
                    ))}
            </ButtonGroup>
        </div>
    );
}
```

### Границы кнопки Границы кнопки Границы кнопки задаются с помощью свойства  `shape` . ```tsx
import React from 'react';
import { ButtonGroup, Button } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div>
            <ButtonGroup size="xs" shape="segmented">
                {Array(3)
                    .fill(true)
                    .map((_, i) => (
                        <Button text={`Button ${i}`} />
                    ))}
            </ButtonGroup>

            <ButtonGroup size="xs" shape="default">
                {Array(3)
                    .fill(true)
                    .map((_, i) => (
                        <Button text={`Button ${i}`} />
                    ))}
            </ButtonGroup>
        </div>
    );
}
```
